variable {V : Type*} [Fintype V] {A : Type*} [LinearOrder A] {B : Type*} [LinearOrder B]

def Prefers (u : A → B) (x y : A) : Prop :=
  u y < u x

def SinglePeaked (peak : A) (u : A → B) : Prop :=
  StrictMonoOn u (Set.Iic peak) ∧ StrictAntiOn u (Set.Ici peak)

def supporters (u : V → A → B) (x y : A) : Finset V :=
  Finset.univ.filter fun i => u i y < u i x

def Beats (u : V → A → B) (x y : A) : Prop :=
  Fintype.card V < 2 * (supporters u x y).card

def IsMedian [LinearOrder A] (peaks : V → A) (m : A) : Prop :=
  Fintype.card V ≤ 2 * (Finset.univ.filter fun i => peaks i ≤ m).card ∧
  Fintype.card V ≤ 2 * (Finset.univ.filter fun i => m ≤ peaks i).card

def CondorcetWinner (u : V → A → B) (m : A) : Prop :=
  ∀ y : A, y ≠ m → Beats u m y

theorem median_voter_theorem
    {peaks : V → A} {u : V → A → B} {m : A}
    (hodd : Odd (Fintype.card V))
    (hsp : ∀ i : V, SinglePeaked (peaks i) (u i))
    (hmed : IsMedian peaks m) :
    ∀ y : A, y ≠ m → Beats u m y := by
  sorry

namespace BayesianScreening

variable {K : Type*} [Field K] [LinearOrder K] [IsStrictOrderedRing K]

def RateOpenUnit (x : K) : Prop :=
  0 < x ∧ x < 1

def RatePositiveUnit (x : K) : Prop :=
  0 < x ∧ x ≤ 1

def truePositiveMass (se π : K) : K :=
  se * π

def falsePositiveMass (sp π : K) : K :=
  (1 - sp) * (1 - π)

def positiveMass (se sp π : K) : K :=
  truePositiveMass se π + falsePositiveMass sp π

def PositivePredictiveValue (se sp π : K) : K :=
  truePositiveMass se π / positiveMass se sp π

def positivePredictiveValueClearsHalf (se sp π : K) : Prop :=
  truePositiveMass se π ≥ falsePositiveMass sp π

theorem PositivePredictiveValue_ge_half_iff_positivePredictiveValueClearsHalf
    {se sp π : K}
    (hse : RatePositiveUnit se) (hsp : RatePositiveUnit sp) (hπ : RateOpenUnit π) :
    PositivePredictiveValue se sp π ≥ 1 / 2 ↔
      positivePredictiveValueClearsHalf se sp π := by
  sorry

end BayesianScreening

